<boltAction type="file" filePath="src/components/DriverPanel.vue">
<script setup lang="ts">
import { ref } from 'vue'

const orders = ref([
  { id: 1, pickup: '123 Main St', dropoff: '456 Oak Ave', price: 120, status: 'pending' },
  { id: 2, pickup: '789 Pine Rd', dropoff: '321 Elm Blvd', price: 95, status: 'pending' }
])

const acceptOrder = (id: number) => {
  const order = orders.value.find(o => o.id === id)
  if (order) order.status = 'accepted'
}

const completeOrder = (id: number) => {
  const order = orders.value.find(o => o.id === id)
  if (order) order.status = 'completed'
}
</script>

<template>
  <div class="driver-panel">
    <h2>Available Orders</h2>
    <div v-for="order in orders" :key="order.id" class="order-card">
      <h3>Order #{{ order.id }}</h3>
      <p><strong>Pickup:</strong> {{ order.pickup }}</p>
      <p><strong>Dropoff:</strong> {{ order.dropoff }}</p>
      <p><strong>Price:</strong> ${{ order.price }}</p>
      <p><strong>Status:</strong> {{ order.status }}</p>

      <button 
        @click="acceptOrder(order.id)" 
        v-if="order.status === 'pending'"
        class="accept-btn"
      >
        Accept Order
      </button>

      <button 
        @click="completeOrder(order.id)" 
        v-if="order.status === 'accepted'"
        class="complete-btn"
      >
        Mark as Completed
      </button>
    </div>
  </div>
</template>

