<boltAction type="file" filePath="src/components/ProductSlider.vue">
<script setup lang="ts">
import { ref, onMounted } from 'vue'

const products = ref([
  { id: 1, name: 'Product 1', price: '$19.99', image: 'https://via.placeholder.com/300x200?text=Product+1' },
  { id: 2, name: 'Product 2', price: '$24.99', image: 'https://via.placeholder.com/300x200?text=Product+2' },
  { id: 3, name: 'Product 3', price: '$29.99', image: 'https://via.placeholder.com/300x200?text=Product+3' },
  { id: 4, name: 'Product 4', price: '$34.99', image: 'https://via.placeholder.com/300x200?text=Product+4' },
  { id: 5, name: 'Product 5', price: '$39.99', image: 'https://via.placeholder.com/300x200?text=Product+5' },
  { id: 6, name: 'Product 6', price: '$44.99', image: 'https://via.placeholder.com/300x200?text=Product+6' }
])

const currentIndex = ref(0)
const visibleItems = ref(3)
const slider = ref<HTMLElement | null>(null)

const updateVisibleItems = () => {
  if (window.innerWidth < 768) {
    visibleItems.value = 1
  } else if (window.innerWidth < 1024) {
    visibleItems.value = 2
  } else {
    visibleItems.value = 3
  }
}

const nextSlide = () => {
  if (currentIndex.value < products.value.length - visibleItems.value) {
    currentIndex.value++
  }
}

const prevSlide = () => {
  if (currentIndex.value > 0) {
    currentIndex.value--
  }
}

const goToSlide = (index: number) => {
  currentIndex.value = index
}

onMounted(() => {
  updateVisibleItems()
  window.addEventListener('resize', updateVisibleItems)
})
</script>

<template>
  <div class="slider-container">
    <div class="slider" ref="slider">
      <button class="arrow prev" @click="prevSlide" aria-label="Previous slide">
        &lt;
      </button>

      <div class="slider-track">
        <div 
          class="slide" 
          v-for="(product, index) in products" 
          :key="product.id"
          :style="{
            transform: `translateX(-${currentIndex * (100 / visibleItems)}%)`,
            flex: `0 0 ${100 / visibleItems}%`
          }"
        >
          <div class="product-card">
            <img :src="product.image" :alt="product.name" class="product-image">
            <h3>{{ product.name }}</h3>
            <p class="price">{{ product.price }}</p>
            <button class="add-to-cart">Add to Cart</button>
          </div>
        </div>
      </div>

      <button class="arrow next" @click="nextSlide" aria-label="Next slide">
        &gt;
      </button>
    </div>

    <div class="pagination">
      <button
        v-for="(_, index) in Math.ceil(products.length / visibleItems)"
        :key="index"
        @click="goToSlide(index * visibleItems)"
        :class="{ active: currentIndex >= index * visibleItems && currentIndex < (index + 1) * visibleItems }"
        aria-label="Go to slide"
      ></button>
    </div>
  </div>
</template>

