<script setup lang="ts">
import { ref, onMounted } from 'vue'

const priceHistory = ref<number[]>([])
const timeLabels = ref<string[]>([])

// Simulate price changes
onMounted(() => {
  // Generate some random price data
  const basePrice = 50000
  for (let i = 0; i < 30; i++) {
    const change = (Math.random() - 0.5) * 1000
    priceHistory.value.push(basePrice + change)
    timeLabels.value.push(`${i}:00`)
  }

  // Update price every 5 seconds
  setInterval(() => {
    const lastPrice = priceHistory.value[priceHistory.value.length - 1]
    const change = (Math.random() - 0.5) * 500
    const newPrice = lastPrice + change
    priceHistory.value.push(newPrice)
    priceHistory.value.shift()

    // Update time labels
    timeLabels.value.shift()
    const now = new Date()
    timeLabels.value.push(`${now.getHours()}:${now.getMinutes().toString().padStart(2, '0')}`)
  }, 5000)
})
</script>

<template>
