    // Load saved datasets from localStorage
    const savedDatasets = localStorage.getItem('jdbc-datasets')
    if (savedDatasets) {
      setDatasets(JSON.parse(savedDatasets))
    }
  }, [])

  const handleLogin = (username: string) => {
    setUser(username)
  }

  const handleLogout = () => {
    setUser(null)
    setResults([])
  }

