      ]
      setResults(mockResults)
    } catch (error) {
      console.error('Query execution failed:', error)
      setResults([])
    } finally {
      setIsLoading(false)
    }
  }

  const saveDataset = (name: string, query: string) => {
    const newDatasets = { ...datasets, [name]: query }
    setDatasets(newDatasets)
    localStorage.setItem('jdbc-datasets', JSON.stringify(newDatasets))
  }

  const deleteDataset = (name: string) => {
    const newDatasets = { ...datasets }
    delete newDatasets[name]
    setDatasets(newDatasets)
    localStorage.setItem('jdbc-datasets', JSON.stringify(newDatasets))
  }

  if (!user) {
    return <Auth onLogin={handleLogin} />
  }

  return (
    <div className="min-h-screen bg-lightsteelblue">
      <Navbar user={user} onLogout={handleLogout} />
      <div className="container px-4 py-8 mx-auto space-y-6">
        <div className="grid grid-cols-1 gap-6 lg:grid-cols-3">
          <div className="lg:col-span-2 space-y-6">
            <QueryEditor 
              onExecute={executeQuery} 
              onSaveDataset={saveDataset} 
            />
            <ResultsViewer results={results} />
          </div>
          <div>
            <DatasetsPanel 
              datasets={datasets} 
              onExecute={executeQuery} 
              onDelete={deleteDataset} 
            />
          </div>
        </div>
      </div>
    </div>
  )
}
