<script setup lang="ts">
import { ref } from 'vue'

const scanResults = ref([
  { file: '/public/index.html', status: 'clean' },
  { file: '/src/main.js', status: 'clean' },
  { file: '/uploads/script.js', status: 'infected', threat: 'Trojan.JS.Downloader' }
])

const isScanning = ref(false)

const runScan = () => {
  isScanning.value = true
  setTimeout(() => {
    // Simulate scan finding new threats
    if (Math.random() > 0.7) {
      scanResults.value.push({
        file: `/uploads/${Math.random().toString(36).substring(7)}.js`,
        status: 'infected',
        threat: 'Trojan.JS.Downloader'
      })
    }
    isScanning.value = false
  }, 2000)
}

const cleanFile = (file: string) => {
  const result = scanResults.value.find(r => r.file === file)
  if (result) {
    result.status = 'clean'
    result.threat = ''
  }
}
</script>

