<script setup lang="ts">
import { ref } from 'vue'

interface Domain {
  id: string
  subdomain: string
  target: string
  verified: boolean
}

const domains = ref<Domain[]>([])
const newDomain = ref({
  subdomain: '',
  target: ''
})
const editingId = ref<string | null>(null)

const addDomain = () => {
  if (!newDomain.value.subdomain || !newDomain.value.target) return

  domains.value.push({
    id: Date.now().toString(),
    subdomain: newDomain.value.subdomain,
    target: newDomain.value.target,
    verified: false
  })

  newDomain.value = { subdomain: '', target: '' }
}

const editDomain = (id: string) => {
  const domain = domains.value.find(d => d.id === id)
  if (domain) {
    newDomain.value = { ...domain }
    editingId.value = id
  }
}

const updateDomain = () => {
  if (!editingId.value) return

  const index = domains.value.findIndex(d => d.id === editingId.value)
  if (index !== -1) {
    domains.value[index] = {
      ...domains.value[index],
      ...newDomain.value
    }
    editingId.value = null
    newDomain.value = { subdomain: '', target: '' }
  }
}

const deleteDomain = (id: string) => {
  domains.value = domains.value.filter(d => d.id !== id)
}

const verifyDomain = (id: string) => {
  const domain = domains.value.find(d => d.id === id)
  if (domain) {
    domain.verified = true
  }
}
</script>

<template>
  <div class="domain-management">
    <h2>Custom Domain Management</h2>

    <div class="domain-form">
      <input
        v-model="newDomain.subdomain"
        placeholder="Subdomain (e.g., blog)"
        class="input-field"
      />
      <input
        v-model="newDomain.target"
        placeholder="Target URL (e.g., https://your-server.com)"
        class="input-field"
      />
      <button
        v-if="!editingId"
        @click="addDomain"
        class="action-button"
      >
        Add Domain
      </button>
      <button
        v-else
        @click="updateDomain"
        class="action-button"
      >
        Update Domain
      </button>
    </div>

    <div class="domain-list">
      <div v-for="domain in domains" :key="domain.id" class="domain-card">
        <div class="domain-info">
          <span class="subdomain">{{ domain.subdomain }}</span>
          <span class="target">{{ domain.target }}</span>
          <span :class="['status', domain.verified ? 'verified' : 'unverified']">
            {{ domain.verified ? 'Verified' : 'Unverified' }}
          </span>
        </div>
        <div class="domain-actions">
          <button @click="editDomain(domain.id)" class="edit-button">Edit</button>
          <button @click="verifyDomain(domain.id)" class="verify-button">Verify</button>
          <button @click="deleteDomain(domain.id)" class="delete-button">Delete</button>
        </div>
      </div>
    </div>
  </div>
</template>

