import { createRouter, createWebHistory } from 'vue-router'
import LoginView from '../views/LoginView.vue'
import DashboardView from '../views/DashboardView.vue'
import UserManagementView from '../views/UserManagementView.vue'
import EnterpriseConfigView from '../views/EnterpriseConfigView.vue'
import ProcessConfigView from '../views/ProcessConfigView.vue'
import MediaUploadView from '../views/MediaUploadView.vue'
import AuthService from '../services/AuthService'

const router = createRouter({
  history: createWebHistory(import.meta.env.BASE_URL),
  routes: [
    {
      path: '/',
      name: 'login',
      component: LoginView,
      meta: { requiresAuth: false }
    },
    {
      path: '/dashboard',
      name: 'dashboard',
      component: DashboardView,
      meta: { requiresAuth: true }
    },
    {
      path: '/users',
      name: 'users',
      component: UserManagementView,
      meta: { requiresAuth: true, requiresAdmin: true }
    },
    {
      path: '/enterprises',
      name: 'enterprises',
      component: EnterpriseConfigView,
      meta: { requiresAuth: true }
    },
    {
      path: '/processes',
      name: 'processes',
      component: ProcessConfigView,
      meta: { requiresAuth: true }
    },
    {
      path: '/media',
      name: 'media',
      component: MediaUploadView,
      meta: { requiresAuth: true }
    }
  ]
})

router.beforeEach((to, from, next) => {
  if (to.meta.requiresAuth && !AuthService.isAuthenticated()) {
    next('/')
  } else if (to.meta.requiresAdmin && !AuthService.isAdmin()) {
    next('/dashboard')
  } else {
    next()
  }
})

export default router
