<script setup lang="ts">
import { ref } from 'vue'

interface MediaItem {
  id: number
  type: 'image' | 'video'
  url: string
  description: string
  uploadedAt: string
}

const mediaItems = ref<MediaItem[]>([
  {
    id: 1,
    type: 'image',
    url: 'https://via.placeholder.com/300',
    description: 'Vehicle before processing',
    uploadedAt: '2023-05-15'
  },
  {
    id: 2,
    type: 'video',
    url: 'https://sample-videos.com/video123/mp4/720/big_buck_bunny_720p_1mb.mp4',
    description: 'Dismantling process',
    uploadedAt: '2023-05-16'
  }
])

const newMedia = ref({
  type: 'image',
  description: ''
})

const fileInput = ref<HTMLInputElement | null>(null)

const uploadMedia = () => {
  if (!fileInput.value?.files?.length) return

  const file = fileInput.value.files[0]
  const reader = new FileReader()

  reader.onload = (e) => {
    const url = e.target?.result as string
    mediaItems.value.push({
      id: mediaItems.value.length + 1,
      type: newMedia.value.type as 'image' | 'video',
      url,
      description: newMedia.value.description,
      uploadedAt: new Date().toISOString().split('T')[0]
    })

    // Reset form
    newMedia.value.description = ''
    if (fileInput.value) {
      fileInput.value.value = ''
    }
  }

  reader.readAsDataURL(file)
}
</script>

<template>
  <div class="media-upload">
    <h1>Media Upload</h1>

    <div class="upload-form">
      <h2>Upload New Media</h2>
      <div class="form-group">
        <label>Media Type</label>
        <select v-model="newMedia.type">
          <option value="image">Image</option>
          <option value="video">Video</option>
        </select>
      </div>
      <div class="form-group">
        <label>Description</label>
        <input v-model="newMedia.description" type="text" />
      </div>
      <div class="form-group">
        <label>File</label>
        <input ref="fileInput" type="file" :accept="newMedia.type === 'image' ? 'image/*' : 'video/*'" />
      </div>
      <button @click="uploadMedia">Upload</button>
    </div>

    <div class="media-gallery">
      <h2>Media Library</h2>
      <div class="media-grid">
        <div v-for="item in mediaItems" :key="item.id" class="media-item">
          <div v-if="item.type === 'image'" class="image-container">
            <img :src="item.url" :alt="item.description" />
          </div>
          <div v-else class="video-container">
            <video controls>
              <source :src="item.url" type="video/mp4" />
              Your browser does not support the video tag.
            </video>
          </div>
