<script setup lang="ts">
import { ref } from 'vue'

const isCharging = ref(false)
const chargeProgress = ref(0)
const timer = ref<NodeJS.Timeout | null>(null)

const startCharging = () => {
  isCharging.value = true
  chargeProgress.value = 0
  timer.value = setInterval(() => {
    chargeProgress.value += 1
    if (chargeProgress.value >= 100) {
      stopCharging()
    }
  }, 100)
}

const stopCharging = () => {
  if (timer.value) {
    clearInterval(timer.value)
    timer.value = null
  }
  isCharging.value = false
}
</script>

<template>
  <div class="charging-control">
    <h2>Charging Control</h2>

    <div class="charging-status">
      <p>Status: {{ isCharging ? 'Charging' : 'Ready' }}</p>
      <div class="progress-bar">
        <div 
          class="progress" 
          :style="{ width: `${chargeProgress}%` }"
        ></div>
      </div>
      <p>{{ chargeProgress }}%</p>
    </div>

    <div class="charging-actions">
      <button 
        @click="startCharging" 
        :disabled="isCharging"
      >Start Charging</button>
      <button 
        @click="stopCharging" 
        :disabled="!isCharging"
      >Stop Charging</button>
    </div>
  </div>
</template>

