<boltAction type="file" filePath="src/stores/dbStore.ts">
import { defineStore } from 'pinia'
import { ref } from 'vue'
import initSqlJs from 'sql.js'

export const useDBStore = defineStore('db', () => {
  const db = ref<any>(null)
  const tables = ref<string[]>([])
  const currentTable = ref<string>('')
  const tableData = ref<any[]>([])

  async function initDB() {
    const SQL = await initSqlJs()
    db.value = new SQL.Database()
  }

  function executeQuery(query: string) {
    if (!db.value) return
    const result = db.value.exec(query)
    if (result.length) {
      tableData.value = result[0].values
    }
    return result
  }

  function getTables() {
    const result = executeQuery("SELECT name FROM sqlite_master WHERE type='table'")
    if (result) {
      tables.value = result[0].values.flat()
    }
  }

  return { db, tables, currentTable, tableData, initDB, executeQuery, getTables }
})
</boltAction>

