<boltAction type="file" filePath="src/components/PackageManagement.vue">
<script setup lang="ts">
import { ref } from 'vue'

const packages = ref([
  { id: 1, type: 'large', status: 'loading', weight: 20, destination: 'Shanghai' },
  { id: 2, type: 'small', status: 'unloading', weight: 2, destination: 'Beijing' }
])

const newPackage = ref({
  type: 'large',
  weight: 0,
  destination: ''
})

const addPackage = () => {
  packages.value.push({
    id: packages.value.length + 1,
    ...newPackage.value,
    status: 'pending'
  })
  newPackage.value = { type: 'large', weight: 0, destination: '' }
}

const updateStatus = (id: number, status: string) => {
  const pkg = packages.value.find(p => p.id === id)
  if (pkg) pkg.status = status
}
</script>

<template>
  <div class="package-management">
    <h2>Package Management</h2>

    <div class="package-form">
      <h3>Add New Package</h3>
      <div class="form-group">
        <label>Type:</label>
        <select v-model="newPackage.type">
          <option value="large">Large</option>
          <option value="small">Small</option>
        </select>
      </div>
      <div class="form-group">
        <label>Weight (kg):</label>
        <input v-model.number="newPackage.weight" type="number">
      </div>
      <div class="form-group">
        <label>Destination:</label>
        <input v-model="newPackage.destination" type="text">
      </div>
      <button @click="addPackage">Add Package</button>
    </div>

    <div class="package-list">
      <h3>Current Packages</h3>
      <table>
        <thead>
          <tr>
            <th>ID</th>
            <th>Type</th>
            <th>Weight</th>
            <th>Destination</th>
            <th>Status</th>
            <th>Actions</th>
          </tr>
        </thead>
        <tbody>
          <tr v-for="pkg in packages" :key="pkg.id">
            <td>{{ pkg.id }}</td>
            <td>{{ pkg.type }}</td>
            <td>{{ pkg.weight }} kg</td>
            <td>{{ pkg.destination }}</td>
            <td>{{ pkg.status }}</td>
            <td>
              <button 
                v-if="pkg.status !== 'loading'" 
                @click="updateStatus(pkg.id, 'loading')"
              >
                Mark Loading
              </button>
              <button 
                v-if="pkg.status !== 'unloading'" 
                @click="updateStatus(pkg.id, 'unloading')"
              >
                Mark Unloading
              </button>
              <button 
                v-if="pkg.status !== 'completed'" 
                @click="updateStatus(pkg.id, 'completed')"
              >
                Complete
              </button>
            </td>
          </tr>
        </tbody>
      </table>
    </div>
  </div>
</template>

