<script setup lang="ts">
import { ref, computed } from 'vue'
import MessageBoard from './components/MessageBoard.vue'
import LoginForm from './components/LoginForm.vue'

type Message = {
  id: number
  author: string
  content: string
  timestamp: string
  replies: Message[]
}

type User = {
  username: string
  isAdmin: boolean
}

const messages = ref<Message[]>([
  {
    id: 1,
    author: 'Admin',
    content: 'Welcome to the message board!',
    timestamp: new Date().toISOString(),
    replies: []
  }
])

const currentUser = ref<User | null>(null)
const searchQuery = ref('')

const filteredMessages = computed(() => {
  if (!searchQuery.value) return messages.value
  const query = searchQuery.value.toLowerCase()
  return messages.value.filter(msg => 
    msg.content.toLowerCase().includes(query) || 
    msg.author.toLowerCase().includes(query)
  )
})

function addMessage(content: string) {
  if (!currentUser.value) return

  const newMessage: Message = {
    id: Date.now(),
    author: currentUser.value.username,
    content,
    timestamp: new Date().toISOString(),
    replies: []
  }
  messages.value.push(newMessage)
}

function addReply(parentId: number, content: string) {
  if (!currentUser.value) return

  const parentMessage = messages.value.find(msg => msg.id === parentId)
  if (!parentMessage) return

  const newReply: Message = {
    id: Date.now(),
    author: currentUser.value.username,
    content,
    timestamp: new Date().toISOString(),
    replies: []
  }
  parentMessage.replies.push(newReply)
}

function deleteMessage(id: number) {
  messages.value = messages.value.filter(msg => msg.id !== id)
}

function login(username: string, password: string) {
  // In a real app, this would be an API call
  currentUser.value = {
    username,
    isAdmin: username === 'admin' && password === 'admin123'
  }
}

function logout() {
  currentUser.value = null
}
</script>

