<script setup lang="ts">
import { ref } from 'vue'

const csvData = ref<string[][]>([])
const headers = ref<string[]>([])
const fileName = ref('')
const delimiter = ref(',')
const outputDelimiter = ref(',')
const showPreview = ref(false)

const handleFileUpload = (event: Event) => {
  const input = event.target as HTMLInputElement
  if (!input.files?.length) return

  const file = input.files[0]
  fileName.value = file.name

  const reader = new FileReader()
  reader.onload = (e) => {
    const content = e.target?.result as string
    parseCsv(content)
  }
  reader.readAsText(file)
}

const parseCsv = (content: string) => {
  const rows = content.split('\n').filter(row => row.trim())
  csvData.value = rows.map(row => row.split(delimiter.value))
  headers.value = csvData.value[0] || []
  showPreview.value = true
}

const convertCsv = () => {
  return csvData.value.map(row => row.join(outputDelimiter.value)).join('\n')
}

const downloadCsv = () => {
  const content = convertCsv()
  const blob = new Blob([content], { type: 'text/csv' })
  const url = URL.createObjectURL(blob)
  const a = document.createElement('a')
  a.href = url
  a.download = `converted_${fileName.value}`
  a.click()
  URL.revokeObjectURL(url)
}
</script>

<template>
  <div class="csv-editor">
    <h1>CSV Conversion Tool</h1>

    <div class="upload-section">
      <input type="file" @change="handleFileUpload" accept=".csv" />
