<script setup lang="ts">
import { computed } from 'vue'

const props = defineProps({
  config: {
    type: Object,
    required: true
  },
  modelValue: {
    type: Object,
    required: true
  },
  errors: {
    type: Object,
    default: () => ({})
  }
})

const emit = defineEmits(['update:modelValue', 'submit'])

const formData = computed({
  get: () => props.modelValue,
  set: (value) => emit('update:modelValue', value)
})

function validateField(fieldId: string, value: any) {
  const field = props.config.fields.find(f => f.id === fieldId)
  if (!field) return true

  if (field.required && !value) {
    return 'This field is required'
  }

  if (field.type === 'email' && value && !/^\S+@\S+\.\S+$/.test(value)) {
    return 'Please enter a valid email address'
  }

  return null
}

function handleSubmit() {
  const errors: Record<string, string> = {}
  let isValid = true

  props.config.fields.forEach(field => {
    if (field.required && !formData.value[field.id]) {
      errors[field.id] = 'This field is required'
      isValid = false
    }
  })

  emit('submit', isValid)
}
</script>

<template>
  <div class="form-container">
    <h2>{{ config.title }}</h2>
    <form @submit.prevent="handleSubmit">
      <div 
        v-for="field in config.fields" 
        :key="field.id"
        class="form-field"
      >
        <label :for="field.id">{{ field.label }}<span v-if="field.required">*</span></label>

        <input
          v-if="['text', 'email', 'number'].includes(field.type)"
          :id="field.id"
          v-model="formData[field.id]"
          :type="field.type"
          :placeholder="field.placeholder"
          :required="field.required"
          @blur="errors[field.id] = validateField(field.id, formData[field.id])"
          class="form-input"
        />

        <select
          v-else-if="field.type === 'select'"
          :id="field.id"
          v-model="formData[field.id]"
          class="form-select"
        >
          <option value="">Select an option</option>
          <option v-for="option in field.options" :key="option" :value="option">
            {{ option }}
          </option>
        </select>

        <div v-else-if="field.type === 'checkbox'" class="checkbox-container">
          <input
            :id="field.id"
            v-model="formData[field.id]"
            type="checkbox"
            class="form-checkbox"
          />
        </div>

        <div v-if="errors[field.id]" class="error-message">
          {{ errors[field.id] }}
        </div>
      </div>

