<script setup lang="ts">
import { ref } from 'vue'
import UpdateList from './components/UpdateList.vue'
import UpdateForm from './components/UpdateForm.vue'

const activeTab = ref('updates')
const updates = ref([
  {
    id: 1,
    title: 'Initial Release',
    version: '1.0.0',
    date: '2023-10-15',
    content: 'First stable release of the application',
    comments: []
  }
])
const editingUpdate = ref(null)

function addUpdate(update) {
  updates.value.unshift({
    ...update,
    id: Date.now(),
    date: new Date().toISOString().split('T')[0],
    comments: []
  })
}

function editUpdate(update) {
  editingUpdate.value = update
}

function saveUpdate(updated) {
  const index = updates.value.findIndex(u => u.id === updated.id)
  if (index !== -1) {
    updates.value[index] = updated
  }
  editingUpdate.value = null
}

function deleteUpdate(id) {
  updates.value = updates.value.filter(u => u.id !== id)
}

function addComment(updateId, comment) {
  const update = updates.value.find(u => u.id === updateId)
  if (update) {
    update.comments.push({
      id: Date.now(),
      text: comment,
      date: new Date().toLocaleString()
    })
  }
}
</script>

<template>
