import React, { useState } from 'react';
import { Search } from 'lucide-react';
import { aiTools, categories, AITool } from './data/aiTools';
import ToolCard from './components/ToolCard';
import ToolDetails from './components/ToolDetails';
import SearchBar from './components/SearchBar';
import CategoryFilter from './components/CategoryFilter';

export default function App() {
  const [searchTerm, setSearchTerm] = useState('');
  const [selectedCategory, setSelectedCategory] = useState('All');
  const [selectedTool, setSelectedTool] = useState<AITool | null>(null);

  const filteredTools = aiTools.filter(tool => {
    const matchesSearch = tool.name.toLowerCase().includes(searchTerm.toLowerCase()) || 
                         tool.description.toLowerCase().includes(searchTerm.toLowerCase());
    const matchesCategory = selectedCategory === 'All' || tool.category === selectedCategory;
    return matchesSearch && matchesCategory;
  });

  const recommendedTools = [...aiTools]
    .sort((a, b) => b.rating - a.rating)
    .slice(0, 3);

  const handleViewDetails = (id: string) => {
    const tool = aiTools.find(t => t.id === id);
    if (tool) setSelectedTool(tool);
  };

  const handleAddReview = (toolId: string, review: { rating: number; comment: string }) => {
    const toolIndex = aiTools.findIndex(t => t.id === toolId);
    if (toolIndex !== -1) {
      const newReview = {
        id: `${toolId}-${Date.now()}`,
        author: 'You',
        rating: review.rating,
        comment: review.comment,
        date: new Date().toISOString().split('T')[0]
      };

      const updatedTool = {
        ...aiTools[toolIndex],
        reviews: [...aiTools[toolIndex].reviews, newReview],
        rating: calculateNewRating(aiTools[toolIndex], review.rating)
      };

      const updatedTools = [...aiTools];
      updatedTools[toolIndex] = updatedTool;

      setSelectedTool(updatedTool);
    }
  };

  const calculateNewRating = (tool: AITool, newRating: number) => {
    const totalRatings = tool.reviews.length + 1;
    const sumRatings = tool.reviews.reduce((sum, review) => sum + review.rating, 0) + newRating;
    return sumRatings / totalRatings;
  };

  return (
    <div className="min-h-screen bg-melon">
      <header className="bg-tomato text-white py-6 shadow-md">
        <div className="container mx-auto px-4">
          <h1 className="text-3xl font-bold text-center">AI Tools Navigator</h1>
          <p className="text-center mt-2">Discover the best AI tools for your needs</p>
        </div>
      </header>

      <main className="container mx-auto px-4 py-8">
        {selectedTool ? (
          <ToolDetails 
            tool={selectedTool}
            onBack={() => setSelectedTool(null)}
            onAddReview={(review) => handleAddReview(selectedTool.id, review)}
          />
        ) : (
          <>
            <SearchBar 
              searchTerm={searchTerm}
              onSearchChange={setSearchTerm}
            />

            <CategoryFilter 
              categories={categories}
              selectedCategory={selectedCategory}
              onSelectCategory={setSelectedCategory}
            />

            <section className="mb-12">
              <h2 className="text-2xl font-bold mb-6 text-center">Recommended Tools</h2>
              <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
                {recommendedTools.map(tool => (
                  <ToolCard 
                    key={tool.id}
                    tool={tool}
                    onViewDetails={handleViewDetails}
                  />
                ))}
              </div>
            </section>

            <section>
              <h2 className="text-2xl font-bold mb-6 text-center">
                {selectedCategory === 'All' ? 'All AI Tools' : `${selectedCategory} Tools`}
              </h2>
              {filteredTools.length === 0 ? (
                <div className="text-center py-12">
                  <Search className="mx-auto h-12 w-12 text-gray-400" />
                  <h3 className="mt-2 text-lg font-medium text-gray-900">No tools found</h3>
                  <p className="mt-1 text-gray-500">Try adjusting your search or filter criteria</p>
                </div>
              ) : (
                <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
                  {filteredTools.map(tool => (
                    <ToolCard 
                      key={tool.id}
                      tool={tool}
                      onViewDetails={handleViewDetails}
                    />
                  ))}
                </div>
              )}
            </section>
          </>
        )}
      </main>

      <footer className="bg-tomato text-white py-6 mt-12">
        <div className="container mx-auto px-4 text-center">
          <p>© {new Date().getFullYear()} AI Tools Navigator. All rights reserved.</p>
        </div>
      </footer>
    </div>
  );
}
