interface Props {
  apiUrl: string;
  githubUrl: string;
}

const { apiUrl, githubUrl } = Astro.props;

// Fetch Bing images
const response = await fetch(apiUrl);
const data = await response.json();
const bingImages = data.images.map(img => ({
  url: `https://www.bing.com${img.url}`,
  title: img.copyright,
  resolutions: {
    small: `https://www.bing.com${img.urlBase}_320x240.jpg`,
    medium: `https://www.bing.com${img.urlBase}_800x600.jpg`,
    large: `https://www.bing.com${img.urlBase}_1920x1080.jpg`
  }
}));

// Fetch GitHub images (simplified example)
const gitImages = [];
try {
  const gitResponse = await fetch(githubUrl);
  const gitData = await gitResponse.json();
  gitImages.push(...gitData.slice(0, 10).map(img => ({
    url: img.download_url,
    title: img.name,
    source: "GitHub"
  })));
} catch (error) {
  console.error("GitHub API error:", error);
}
---

