<boltAction type="file" filePath="src/App.tsx">
import React, { useState } from 'react'
import { Upload, Database, History, Settings, ChevronDown, ChevronUp } from 'lucide-react'

function App() {
  const [activeTab, setActiveTab] = useState('migrate')
  const [versions, setVersions] = useState([
    { id: 1, name: 'v1.0.0', date: '2023-10-15' },
    { id: 2, name: 'v1.1.0', date: '2023-11-20' },
    { id: 3, name: 'v2.0.0', date: '2024-01-05' }
  ])
  const [oldSchema, setOldSchema] = useState('')
  const [newSchema, setNewSchema] = useState('')
  const [migrationScript, setMigrationScript] = useState('')
  const [expandedVersion, setExpandedVersion] = useState<number | null>(null)

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>, type: string) => {
    const file = e.target.files?.[0]
    if (file) {
      const reader = new FileReader()
      reader.onload = (event) => {
        const content = event.target?.result as string
        if (type === 'old') setOldSchema(content)
        else setNewSchema(content)
      }
      reader.readAsText(file)
    }
  }

  const generateMigration = () => {
    // In a real app, this would use a proper diffing algorithm
    setMigrationScript(`-- Migration script generated at ${new Date().toISOString()}\n\n`)
  }

  const toggleVersion = (id: number) => {
    setExpandedVersion(expandedVersion === id ? null : id)
  }

  return (
    <div className="min-h-screen bg-moccasin">
      <header className="bg-sandybrown p-4 shadow-md">
        <div className="container mx-auto flex justify-between items-center">
          <h1 className="text-2xl font-bold text-white flex items-center">
            <Database className="mr-2" /> Schema Migrator
          </h1>
          <nav className="flex space-x-4">
            <button 
              onClick={() => setActiveTab('migrate')}
              className={`px-4 py-2 rounded-lg ${activeTab === 'migrate' ? 'bg-white text-sandybrown' : 'text-white'}`}
            >
              <Upload className="inline mr-2" /> Migrate
            </button>
            <button 
              onClick={() => setActiveTab('versions')}
              className={`px-4 py-2 rounded-lg ${activeTab === 'versions' ? 'bg-white text-sandybrown' : 'text-white'}`}
            >
              <History className="inline mr-2" /> Versions
            </button>
          </nav>
        </div>
      </header>

      <main className="container mx-auto p-4">
        {activeTab === 'migrate' && (
          <div className="bg-white rounded-lg shadow-lg p-6">
            <h2 className="text-xl font-semibold mb-4 text-sandybrown">Schema Migration</h2>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-6 mb-6">
              <div className="border-2 border-sandybrown rounded-lg p-4">
                <h3 className="font-medium mb-2">Old Schema</h3>
                <label className="block mb-4">
                  <span className="sr-only">Upload old schema</span>
                  <input 
                    type="file" 
                    onChange={(e) => handleFileUpload(e, 'old')}
                    className="block w-full text-sm text-gray-500
                      file:mr-4 file:py-2 file:px-4
                      file:rounded-full file:border-0
                      file:text-sm file:font-semibold
                      file:bg-sandybrown file:text-white
                      hover:file:bg-sandybrown/80"
                  />
                </label>
                <textarea 
                  value={oldSchema}
                  onChange={(e) => setOldSchema(e.target.value)}
                  className="w-full h-64 p-2 border border-gray-300 rounded"
                  placeholder="Or paste your old schema here..."
                />
              </div>

              <div className="border-2 border-sandybrown rounded-lg p-4">
                <h3 className="font-medium mb-2">New Schema</h3>
                <label className="block mb-4">
                  <span className="sr-only">Upload new schema</span>
                  <input 
                    type="file" 
                    onChange={(e) => handleFileUpload(e, 'new')}
                    className="block w-full text-sm text-gray-500
                      file:mr-4 file:py-2 file:px-4
                      file:rounded-full file:border-0
                      file:text-sm file:font-semibold
                      file:bg-sandybrown file:text-white
                      hover:file:bg-sandybrown/80"
                  />
                </label>
                <textarea 
                  value={newSchema}
                  onChange={(e) => setNewSchema(e.target.value)}
                  className="w-full h-64 p-2 border border-gray-300 rounded"
                  placeholder="Or paste your new schema here..."
                />
              </div>
            </div>

            <div className="flex justify-center">
              <button 
                onClick={generateMigration}
                disabled={!oldSchema || !newSchema}
                className="bg-sandybrown text-white px-6 py-3 rounded-lg font-medium disabled:opacity-50"
              >
                Generate Migration Script
              </button>
            </div>

            {migrationScript && (
              <div className="mt-6 border-2 border-sandybrown rounded-lg p-4">
                <h3 className="font-medium mb-2">Migration Script</h3>
                <pre className="bg-gray-100 p-4 rounded overflow-x-auto">
                  {migrationScript}
                </pre>
              </div>
            )}
          </div>
        )}

        {activeTab === 'versions' && (
          <div className="bg-white rounded-lg shadow-lg p-6">
            <h2 className="text-xl font-semibold mb-4 text-sandybrown">Schema Versions</h2>

            <div className="space-y-2">
              {versions.map(version => (
                <div key={version.id} className="border border-sandybrown rounded-lg overflow-hidden">
                  <div 
                    className="flex justify-between items-center p-4 bg-sandybrown/10 cursor-pointer"
                    onClick={() => toggleVersion(version.id)}
                  >
                    <div>
                      <span className="font-medium">{version.name}</span>
                      <span className="text-sm text-gray-500 ml-2">{version.date}</span>
                    </div>
                    {expandedVersion === version.id ? <ChevronUp /> : <ChevronDown />}
                  </div>

                  {expandedVersion === version.id && (
                    <div className="p-4 bg-white">
                      <pre className="bg-gray-100 p-4 rounded overflow-x-auto">
                        {/* Schema content would go here */}
                        {`-- Schema version ${version.name}\n-- Generated on ${version.date}\n\n-- Tables and structure would be displayed here`}
                      </pre>
                    </div>
                  )}
                </div>
              ))}
            </div>
          </div>
        )}
      </main>

      <footer className="bg-sandybrown text-white p-4 mt-8">
        <div className="container mx-auto text-center">
          <p>Database Schema Migration Tool © {new Date().getFullYear()}</p>
        </div>
      </footer>
    </div>
  )
}

export default App
</boltAction>

