<script setup lang="ts">
import { ref, onMounted } from 'vue'

interface Event {
  id: string
  type: string
  data: any
  timestamp: Date
  status: 'pending' | 'processing' | 'completed' | 'failed'
}

const events = ref<Event[]>([])
const eventLog = ref<string[]>([])
const activeEvents = ref<number>(0)

const colors = {
  platinum: '#E5E4E2',
  midnightBlue: '#191970'
}

const eventTypes = [
  'userClick',
  'dataFetch',
  'calculation',
  'notification',
  'systemAlert'
]

const generateRandomEvent = (): Event => {
  const types = eventTypes
  const type = types[Math.floor(Math.random() * types.length)]
  return {
    id: Math.random().toString(36).substring(2, 9),
    type,
    data: { value: Math.floor(Math.random() * 100) },
    timestamp: new Date(),
    status: 'pending'
  }
}

const processEvent = async (event: Event) => {
  event.status = 'processing'
  activeEvents.value++
  logEvent(`Processing event ${event.id} (${event.type})`)

  // Simulate async processing with random delay
  const delay = Math.random() * 2000 + 500
  await new Promise(resolve => setTimeout(resolve, delay))

  // Randomly fail some events
  const shouldFail = Math.random() < 0.2
  if (shouldFail) {
    event.status = 'failed'
    logEvent(`Event ${event.id} failed`)
  } else {
    event.status = 'completed'
    logEvent(`Event ${event.id} completed successfully`)
  }
  activeEvents.value--
}

const triggerEvent = () => {
  const newEvent = generateRandomEvent()
  events.value.unshift(newEvent)
  logEvent(`New event triggered: ${newEvent.id} (${newEvent.type})`)
  processEvent(newEvent)
}

const triggerMultipleEvents = (count: number) => {
  for (let i = 0; i < count; i++) {
    setTimeout(() => triggerEvent(), i * 300)
  }
}

const logEvent = (message: string) => {
  const timestamp = new Date().toLocaleTimeString()
  eventLog.value.unshift(`[${timestamp}] ${message}`)
  if (eventLog.value.length > 50) {
    eventLog.value.pop()
  }
}

const getStatusColor = (status: string) => {
  switch (status) {
    case 'completed': return 'green'
    case 'failed': return 'red'
    case 'processing': return 'orange'
    default: return 'gray'
  }
}

onMounted(() => {
  // Start with 3 random events
  triggerMultipleEvents(3)
})
</script>

<template>
  <div class="app-container" :style="{ backgroundColor: colors.platinum }">
    <h1 :style="{ color: colors.midnightBlue }">Event Manager</h1>

    <div class="controls">
      <button 
        @click="triggerEvent"
        :style="{ backgroundColor: colors.midnightBlue, color: 'white' }"
      >
        Trigger Single Event
      </button>
      <button 
        @click="() => triggerMultipleEvents(5)"
        :style="{ backgroundColor: colors.midnightBlue, color: 'white' }"
      >
        Trigger 5 Events
      </button>
      <div class="stats">
        Active Events: {{ activeEvents }} | Total Events: {{ events.length }}
      </div>
    </div>

    <div class="panels">
      <div class="events-panel">
        <h2 :style="{ color: colors.midnightBlue }">Recent Events</h2>
        <div class="event-list">
          <div 
            v-for="event in events" 
            :key="event.id"
            class="event-item"
            :style="{ 
              borderColor: colors.midnightBlue,
              backgroundColor: getStatusColor(event.status) === 'gray' ? 'white' : 'transparent'
            }"
          >
            <div class="event-type" :style="{ color: colors.midnightBlue }">
              {{ event.type }}
            </div>
            <div class="event-status" :style="{ color: getStatusColor(event.status) }">
              {{ event.status }}
            </div>
            <div class="event-time">
              {{ event.timestamp.toLocaleTimeString() }}
