import { createRouter, createWebHistory } from 'vue-router'
import Login from '../views/LoginView.vue'
import Dashboard from '../views/DashboardView.vue'
import Applications from '../views/ApplicationsView.vue'
import Tasks from '../views/TasksView.vue'
import Invoices from '../views/InvoicesView.vue'
import Feedback from '../views/FeedbackView.vue'
import Roles from '../views/RolesView.vue'

const router = createRouter({
  history: createWebHistory(import.meta.env.BASE_URL),
  routes: [
    {
      path: '/',
      name: 'login',
      component: Login
    },
    {
      path: '/dashboard',
      name: 'dashboard',
      component: Dashboard,
      children: [
        { path: 'applications', component: Applications },
        { path: 'tasks', component: Tasks },
        { path: 'invoices', component: Invoices },
        { path: 'feedback', component: Feedback },
        { path: 'roles', component: Roles }
      ]
    }
  ]
})

export default router
</boltAction>

