            <option value="viewer">Viewer</option>
          </select>
        </div>
        <button @click="handleCreateUser" class="create-button">Create User</button>
      </div>

      <div class="user-list">
        <h4>Existing Users</h4>
        <table>
          <thead>
            <tr>
              <th>Username</th>
              <th>Role</th>
              <th>Actions</th>
            </tr>
          </thead>
          <tbody>
            <tr v-for="user in users" :key="user.id">
              <td>{{ user.username }}</td>
              <td>{{ user.role }}</td>
              <td>
                <button class="edit-button">Edit</button>
                <button 
                  @click="() => handleDeleteUser(user.id)" 
                  class="delete-button"
                >
                  Delete
                </button>
              </td>
            </tr>
          </tbody>
        </table>
      </div>
    </div>

    <div class="permission-management">
