            <td>User API</td>
            <td>
              <input 
                type="checkbox" 
                :checked="apiPermissions.find(p => p.userId === user.id && p.apiId === 1)?.canRead || false"
                @change="(e) => handleUpdatePermission(user.id, 1, 'canRead', e.target.checked)"
              />
            </td>
            <td>
