<script setup lang="ts">
import { ref, computed, onMounted } from 'vue'

// Team scores
const teamAScore = ref(0)
const teamBScore = ref(0)

// Score increment options
const scoreOptions = [1, 2, 3, 5]

// Speech synthesis
const synth = window.speechSynthesis
const isSpeaking = ref(false)

// Announce score
function announceScore() {
  if (synth.speaking) {
    synth.cancel()
  }

  const utterance = new SpeechSynthesisUtterance(
    `Team A: ${teamAScore.value}, Team B: ${teamBScore.value}`
  )
  synth.speak(utterance)
  isSpeaking.value = true

  utterance.onend = () => {
    isSpeaking.value = false
  }
}

// Add score to team
function addScore(team: 'A' | 'B', points: number) {
  if (team === 'A') {
    teamAScore.value += points
  } else {
    teamBScore.value += points
  }
  announceScore()
}

// Reset scores
function resetScores() {
  teamAScore.value = 0
  teamBScore.value = 0
  if (synth.speaking) {
    synth.cancel()
  }
}

// Responsive layout
const isMobile = ref(window.innerWidth < 768)
window.addEventListener('resize', () => {
  isMobile.value = window.innerWidth < 768
})
</script>

<template>
  <div class="score-counter">
    <h1>VS Score Counter</h1>

    <div class="teams-container">
      <!-- Team A -->
      <div class="team" :style="{ backgroundColor: 'rosybrown' }">
        <h2>Team A</h2>
        <div class="score">{{ teamAScore }}</div>
        <div class="buttons">
          <button 
            v-for="points in scoreOptions" 
            :key="`A-${points}`"
            @click="addScore('A', points)"
          >
            +{{ points }}
          </button>
        </div>
      </div>

      <!-- Team B -->
      <div class="team" :style="{ backgroundColor: 'rosybrown' }">
        <h2>Team B</h2>
        <div class="score">{{ teamBScore }}</div>
        <div class="buttons">
          <button 
            v-for="points in scoreOptions" 
            :key="`B-${points}`"
            @click="addScore('B', points)"
          >
            +{{ points }}
          </button>
        </div>
      </div>
    </div>

    <div class="controls">
      <button @click="announceScore" :disabled="isSpeaking">
        {{ isSpeaking ? 'Announcing...' : 'Announce Score' }}
      </button>
