<script setup lang="ts">
import { ref } from 'vue'

const audioBlob = ref<Blob | null>(null)
const audioUrl = ref('')
const isRecording = ref(false)
const selectedModel = ref('default')
const models = ref([
  { id: 'default', name: 'Default Voice' },
  { id: 'deep', name: 'Deep Voice' },
  { id: 'high', name: 'High Pitch' },
  { id: 'robot', name: 'Robot Voice' }
])

let mediaRecorder: MediaRecorder | null = null
let audioChunks: Blob[] = []

const startRecording = async () => {
  try {
    const stream = await navigator.mediaDevices.getUserMedia({ audio: true })
    mediaRecorder = new MediaRecorder(stream)
    isRecording.value = true
    audioChunks = []

    mediaRecorder.ondataavailable = (e) => {
      audioChunks.push(e.data)
    }

    mediaRecorder.onstop = () => {
      audioBlob.value = new Blob(audioChunks)
      audioUrl.value = URL.createObjectURL(audioBlob.value)
    }

    mediaRecorder.start()
  } catch (err) {
    console.error('Error accessing microphone:', err)
  }
}

const stopRecording = () => {
  if (mediaRecorder) {
    mediaRecorder.stop()
    isRecording.value = false
    mediaRecorder.stream.getTracks().forEach(track => track.stop())
  }
}

const convertVoice = () => {
  // In a real app, this would send the audio to a conversion API
  console.log('Converting voice with model:', selectedModel.value)
}
</script>

