<script setup lang="ts">
import { ref } from 'vue'

const videoUrl = ref('')
const resultUrl = ref('')
const isLoading = ref(false)
const errorMessage = ref('')

const platforms = [
  { name: 'TikTok', pattern: /tiktok\.com/ },
  { name: 'Douyin', pattern: /douyin\.com/ },
  { name: 'Kuaishou', pattern: /kuaishou\.com/ },
  { name: 'Instagram', pattern: /instagram\.com/ }
]

const removeWatermark = () => {
  if (!videoUrl.value) {
    errorMessage.value = 'Please enter a video URL'
    return
  }

  isLoading.value = true
  errorMessage.value = ''

  // Simulate processing delay
  setTimeout(() => {
    try {
      const platform = platforms.find(p => p.pattern.test(videoUrl.value))
      if (!platform) {
        throw new Error('Unsupported platform')
      }

      // In a real app, this would call an API to process the video
      resultUrl.value = `Processed video from ${platform.name}`
    } catch (err) {
      errorMessage.value = err.message
    } finally {
      isLoading.value = false
    }
  }, 1500)
}
</script>

<template>
