import { ref } from 'vue'

interface Task {
  id: string
  filename: string
  status: 'queued' | 'processing' | 'completed' | 'failed'
  progress: number
  server: string
  startTime: Date
}

const tasks = ref<Task[]>([
  {
    id: '1',
    filename: 'video1.mp4',
    status: 'completed',
    progress: 100,
    server: 'Server 1',
    startTime: new Date(Date.now() - 3600000)
  },
  {
    id: '2',
    filename: 'video2.avi',
    status: 'processing',
    progress: 65,
    server: 'Server 2',
    startTime: new Date(Date.now() - 1800000)
  },
  {
    id: '3',
    filename: 'video3.mov',
    status: 'queued',
    progress: 0,
    server: '',
    startTime: new Date()
  }
])

const cancelTask = (id: string) => {
  tasks.value = tasks.value.filter(task => task.id !== id)
}
</script>

