<boltAction type="file" filePath="src/utils/workerPool.ts">
class WorkerPool {
  private workers: Worker[]
  private taskQueue: Array<{task: any, resolve: Function, reject: Function}>
  private activeWorkers: number

  constructor(poolSize: number, workerScript: string) {
    this.workers = []
    this.taskQueue = []
    this.activeWorkers = 0

    for (let i = 0; i < poolSize; i++) {
      const worker = new Worker(workerScript)
      worker.onmessage = this.handleWorkerMessage.bind(this, worker)
      worker.onerror = this.handleWorkerError.bind(this, worker)
      this.workers.push(worker)
    }
  }

  private handleWorkerMessage(worker: Worker, e: MessageEvent) {
    const task = this.taskQueue.shift()
    if (task) {
      task.resolve(e.data)
    }
    this.activeWorkers--
    this.processNextTask()
  }

  private handleWorkerError(worker: Worker, e: ErrorEvent) {
    const task = this.taskQueue.shift()
    if (task) {
      task.reject(e.error)
    }
    this.activeWorkers--
    this.processNextTask()
  }

  private processNextTask() {
    if (this.taskQueue.length === 0 || this.activeWorkers >= this.workers.length) {
      return
    }

    const nextTask = this.taskQueue[0]
    const availableWorker = this.workers.find(w => !w.busy)

    if (availableWorker && nextTask) {
      availableWorker.busy = true
      this.activeWorkers++
      availableWorker.postMessage(nextTask.task)
    }
  }

  public async execute(task: any): Promise<any> {
    return new Promise((resolve, reject) => {
      this.taskQueue.push({ task, resolve, reject })
      this.processNextTask()
    })
  }

  public getQueueLength(): number {
    return this.taskQueue.length
  }

  public getActiveWorkers(): number {
    return this.activeWorkers
  }
}

export default WorkerPool
</boltAction>

<boltAction type="file" filePath="src/utils/taskScheduler.ts">
import WorkerPool from './workerPool'

class TaskScheduler {
  private workerPool: WorkerPool
  private serverCapacities: Map<string, number>
  private serverLoads: Map<string, number>

  constructor(poolSize: number, workerScript: string) {
    this.workerPool = new WorkerPool(poolSize, workerScript)
    this.serverCapacities = new Map()
    this.serverLoads = new Map()
  }

  public addServer(serverId: string, capacity: number) {
    this.serverCapacities.set(serverId, capacity)
    this.serverLoads.set(serverId, 0)
  }

  public removeServer(serverId: string) {
    this.serverCapacities.delete(serverId)
    this.serverLoads.delete(serverId)
  }

  public updateServerLoad(serverId: string, load: number) {
    if (this.serverLoads.has(serverId)) {
      this.serverLoads.set(serverId, load)
    }
  }

  public async scheduleTask(task: any): Promise<any> {
    const optimalServer = this.findOptimalServer()
    if (!optimalServer) {
      throw new Error('No available servers')
    }

    this.updateServerLoad(optimalServer, (this.serverLoads.get(optimalServer) || 0) + 1)

    try {
      const result = await this.workerPool.execute({
        ...task,
        server: optimalServer
      })

      this.updateServerLoad(optimalServer, (this.serverLoads.get(optimalServer) || 0) - 1)
      return result
    } catch (error) {
      this.updateServerLoad(optimalServer, (this.serverLoads.get(optimalServer) || 0) - 1)
      throw error
    }
  }

  private findOptimalServer(): string | null {
    let bestServer: string | null = null
    let bestScore = Infinity

    for (const [serverId, capacity] of this.serverCapacities) {
      const currentLoad = this.serverLoads.get(serverId) || 0
      const availableCapacity = capacity - currentLoad

      if (availableCapacity > 0) {
        const score = currentLoad / capacity
        if (score < bestScore) {
          bestScore = score
          bestServer = serverId
        }
      }
    }

    return bestServer
  }
}

export default TaskScheduler
</boltAction>

<boltAction type="file" filePath="src/utils/mediaProcessor.ts">
class MediaProcessor {
  static async processVideo(file: File, options: any): Promise<any> {
    // Simulate processing time based on file size and options
    const processingTime = Math.min(file.size / 1000000, 10000) // Max 10 seconds

    return new Promise((resolve) => {
      setTimeout(() => {
        resolve({
          originalName: file.name,
          processedName: `${file.name.split('.')[0]}_processed.${options.format}`,
          size: file.size,
          processingTime: processingTime / 1000,
          options
        })
      }, processingTime)
    })
  }
}

export default MediaProcessor
