<script setup lang="ts">
import { ref } from 'vue'

const slides = ref([
  {
    id: 1,
    title: 'First Slide',
    description: 'This is the first slide with important information',
    image: 'https://picsum.photos/800/400?random=1',
    ctaLink: '#slide1'
  },
  {
    id: 2,
    title: 'Second Slide',
    description: 'Discover more about our second featured item',
    image: 'https://picsum.photos/800/400?random=2',
    ctaLink: '#slide2'
  },
  {
    id: 3,
    title: 'Third Slide',
    description: 'Learn about our third exciting product',
    image: 'https://picsum.photos/800/400?random=3',
    ctaLink: '#slide3'
  }
])

const currentSlide = ref(0)

const nextSlide = () => {
  currentSlide.value = (currentSlide.value + 1) % slides.value.length
}

const prevSlide = () => {
  currentSlide.value = (currentSlide.value - 1 + slides.value.length) % slides.value.length
}

const goToSlide = (index: number) => {
  currentSlide.value = index
}
</script>

<template>
  <div class="slider-container">
    <div class="slider-wrapper">
      <div 
        class="slider"
        :style="{ transform: `translateX(-${currentSlide * 100}%)` }"
      >
        <div 
          v-for="(slide, index) in slides" 
          :key="slide.id" 
          class="slide"
        >
          <img :src="slide.image" :alt="slide.title" class="slide-image">
          <div class="slide-content">
            <h2>{{ slide.title }}</h2>
            <p>{{ slide.description }}</p>
            <a :href="slide.ctaLink" class="cta-button">Learn More</a>
          </div>
        </div>
      </div>
    </div>

    <button @click="prevSlide" class="nav-button prev">❮</button>
    <button @click="nextSlide" class="nav-button next">❯</button>

    <div class="dots">
      <button
        v-for="(slide, index) in slides"
        :key="slide.id"
        @click="goToSlide(index)"
        :class="{ active: currentSlide === index }"
        class="dot"
      ></button>
    </div>
  </div>
</template>

